  let image = &quot;%2fPCUP%2fReligion-PNG%2fLamashtu.png&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;#symbole1&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td id=&quot;symbole1&quot; style=&quot;text-align:center;&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux aux fid&#232;les de la divinit&#233; indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Lamashtu (technique).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/%2fPCUP%2fReligion-PNG%2fLamashtu.png&quot; style=&quot;max-height:70px; max-width:70px&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br/&gt;commune chez&lt;br/&gt;les fid&#232;les&lt;br/&gt;de &lt;a class=&quot;pagelink&quot; href=&quot;Lamashtu-(Technique).html&quot; title=&quot;Lamashtu&quot;&gt;Lamashtu&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Masque de la m&#232;re d&#233;mone&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Gods/Dieux de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux et magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Gods and Magic, Faiths of Purity, Faiths of Balance, Faiths of Corruption/Dieux et magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoG&amp;M.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; faible ; &lt;b&gt;NLS&lt;/b&gt; 3 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-La-T&#234;te.html&quot; title=&quot;Objets merveilleux port&#233;s sur la t&#234;te&quot;&gt;t&#234;te&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 3 600 po ; &lt;b&gt;Poids&lt;/b&gt; 0,5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Ce masque primitif repr&#233;sentant une hy&#232;ne est en g&#233;n&#233;ral fait de cuir mais certains sont en m&#233;tal mall&#233;able comme le cuivre, voire taill&#233;s dans le cr&#226;ne d’un animal. Le personnage b&#233;n&#233;ficie d’un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;. Il peut sentir quand des cr&#233;atures voisines sont en chaleur ou fertiles (les cr&#233;atures qui peuvent se reproduire tout le temps, comme les humains, sont toujours fertiles, &#224; moins d’&#234;tre st&#233;riles).&lt;br /&gt;&lt;br /&gt;Si le personnage est un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Lamashtu-(Technique).html&quot; title=&quot;Lamashtu&quot;&gt;Lamashtu&lt;/a&gt;, le masque compte comme un &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;, et un trou pour un troisi&#232;me œil appara&#238;t sur le front. Il peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ii.html&quot; title=&quot;Convocation de monstres II&quot;&gt;convocation de monstres II&lt;/a&gt;&lt;/i&gt; une fois par jour pour convoquer une &lt;a class=&quot;pagelink&quot; href=&quot;Hy&#232;ne.html&quot; title=&quot;Hy&#232;ne&quot;&gt;hy&#232;ne&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREFIELONE&quot; title=&quot;Les arch&#233;types&quot;&gt;fi&#233;lonne&lt;/a&gt;, qui lui ob&#233;it comme s’il parlait la m&#234;me langue. Il peut se reproduire avec les animaux dont la cat&#233;gorie de taille est voisine de la sienne. La prog&#233;niture d&#39;une telle union est un membre de la race de la m&#232;re avec l&#39;arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREFIELONE&quot; title=&quot;Les arch&#233;types&quot;&gt;fi&#233;lon&lt;/a&gt; et h&#233;rite des caract&#233;ristiques monstrueuses de la race du p&#232;re.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d&#39;objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Faune-Ou-De-La-Flore.html&quot; title=&quot;D&#233;tection de la faune ou de la flore&quot;&gt;d&#233;tection de la faune ou de la flore&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ii.html&quot; title=&quot;Convocation de monstres II&quot;&gt;convocation de monstres II&lt;/a&gt;&lt;/i&gt;, le cr&#233;ateur doit avoir 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 1 800 po
&lt;/div&gt;
